{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The rescue team gathers at the edge of the ruined city.",
      "visual_description": "A windswept ridge overlooking a shattered royal city at dusk, broken spires silhouetted against a bruised sky. Mara unrolls a map on a stone while the tin fox sniffs the wind and the oracle lamp flickers nearby.",
      "characters": ["mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 2,
      "caption": "Mara plots a route past the castle gates.",
      "visual_description": "Close-up of an ink-stained map weighted down by a brass compass, Mara's finger tracing a red line around an enormous iron gate drawn at the map's center, lamp glow casting one yellow eye on the parchment.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp warns against the obvious road.",
      "visual_description": "A narrow alley mouth framed by torn royal banners; the lamp hovers mid-air with its single flame-eye wide, casting a warning shadow shaped like a gate across Mara's worried face.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "The glass diver arrives through a cracked shop window.",
      "visual_description": "A dim storefront with a tall broken pane rippling like water; the glass diver emerges headfirst from the surface, helmet glinting, coat scattering reflected streetlamp colors across the cobblestones.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "Introductions in the abandoned customs house.",
      "visual_description": "Interior of a dusty municipal office with overturned chairs. The sleeping tax collector slumps over a ledger pillow, stamped papers stuck to his sleeves, while the glass diver leans in curiously and the tin fox tilts its head.",
      "characters": ["glass_diver", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "The tax collector mumbles useless directions in his sleep.",
      "visual_description": "Close shot of the sleeping tax collector drooling onto a ledger; a speech bubble of nonsense numerals floats above him. Mara writes notes anyway, the oracle lamp rolling its flame-eye in disbelief.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 7,
      "caption": "The tin fox scouts an armored patrol route.",
      "visual_description": "From a low rooftop perspective, the clockwork fox peers down with blue glass eyes glinting; below in the street, abandoned plate armor stands eerily upright in formation, lit by torch sockets long burned out.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "Rumors of a great winged beast turn out to be wind.",
      "visual_description": "A vast empty plaza where wind howls through the ribcage of a ruined cathedral, making a deep roar. Mara and the glass diver crouch behind a fallen statue, realizing the sound is only air through stone.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "Frightened faces watch from boarded windows.",
      "visual_description": "A narrow lane of shuttered houses; pale eyes peek through slats in the wood. The oracle lamp dims politely so the watchers won't be seen, while Mara presses a finger to her lips.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 10,
      "caption": "The glass diver slips through a tower mirror.",
      "visual_description": "A leaning cursed tower's tall mirror ripples like a vertical pond. The diver steps halfway in, coat reflecting fractured chandelier light, while the tin fox waits at the threshold with its key-wind tail twitching.",
      "characters": ["glass_diver", "tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "Inside the tower, the captive is found behind a magic door.",
      "visual_description": "A circular chamber sealed by a glowing rune door. The glass diver presses a gloved palm to the sigils; the oracle lamp hovers beside the lock, its single flame-eye matching the rune color exactly.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "The lamp speaks the unlocking word.",
      "visual_description": "Close-up of the oracle lamp, flame stretched into the shape of a spoken letter; the rune door splits down the middle in a flare of pale gold, casting long shadows of the glass diver across the floor.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "Mara maps an escape avoiding the banner-hung avenue.",
      "visual_description": "Street level view of an avenue choked with rotting royal banners hanging like red curtains. Mara crouches with her compass spinning wildly, the tin fox at her boot pointing its nose down a side alley.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "The sleeping tax collector is dragged along as cover.",
      "visual_description": "Mara and the glass diver hauling the dozing official by his elbows down a moonlit street; his ledger trails papers like a stamped breadcrumb path. He snores contentedly through it all.",
      "characters": ["mara_the_cartographer", "glass_diver", "sleeping_tax_collector"]
    },
    {
      "scene_number": 15,
      "caption": "Armored patrols clatter past, fooled by stamped papers.",
      "visual_description": "An empty suit-armor patrol pauses to inspect a fluttering wax-sealed document the tax collector dropped. Around the corner, the tin fox peeks out, its tail's key turning silently.",
      "characters": ["sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "The team races toward the river bridge.",
      "visual_description": "A long stone bridge over black water, mist curling at its base. Mara sprints in front, coat flaring, the glass diver behind her with the tax collector slung over his shoulder, oracle lamp swinging on a chain.",
      "characters": ["mara_the_cartographer", "glass_diver", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "The tin fox holds the far end as the bridge cracks.",
      "visual_description": "Mid-bridge stones split and tumble into the river below. The clockwork fox stands braced at the far gatehouse, blue eyes blazing, while the runners leap the widening gap in a shower of dust.",
      "characters": ["tin_fox", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 18,
      "caption": "Safely across, the rescue team looks back at the ruined city.",
      "visual_description": "A grassy bluff at dawn beyond the bridge. Mara folds her map, the glass diver removes his helmet for a breath of cool air, the oracle lamp dims to a soft ember, the tin fox sits proudly, and the tax collector finally, slowly, opens one eye.",
      "characters": ["mara_the_cartographer", "glass_diver", "oracle_lamp", "tin_fox", "sleeping_tax_collector"]
    }
  ]
}

